    use super::*;
    #[test]
    fn parses_or_falls_back() {
        assert_eq!(run(), (41, 1.5));
    }
    #[test]
    fn the_type_argument_decides_the_result_type() {
        let n: u8 = parse_or!("7", u8, 0);
        assert_eq!(n, 7);
        assert_eq!(parse_or!("-2", i64, 99), -2);
    }
