macro_rules! max_of {
    ($a:expr) => { $a };
    ($a:expr, $($rest:expr),+) => {{
        let r = max_of!($($rest),+);
        if $a > r { $a }
    }};
}

pub fn run() -> i32 {
    max_of!(3, 17, 8, 2)
}

exercises.tests:
