    use super::*;
    #[test]
    fn finds_the_largest() {
        assert_eq!(run(), 17);
    }
    #[test]
    fn works_at_every_length() {
        assert_eq!(max_of!(5), 5);
        assert_eq!(max_of!(5, 9), 9);
        assert_eq!(max_of!(9, 5), 9);
        assert_eq!(max_of!(1, 2, 3, 4, 5, 6, 7, 8), 8);
    }
}

